#!/usr/bin/env python3
import base64
import gzip
import hashlib

_PAYLOAD = ""

_SOURCE = gzip.decompress(base64.b64decode(_PAYLOAD, validate=True))
_SOURCE_SHA256 = hashlib.sha256(_SOURCE).hexdigest()
if _SOURCE_SHA256 != "48669a22f2e6fe8f444320aa73cca82f8685520f88bad77f882b573395fbbb56":
    raise RuntimeError("A9_SOURCE_SHA256_MISMATCH")
exec(compile(_SOURCE.decode("utf-8"), __file__, "exec"), globals(), globals())
